PRIOR_ARCHIVE_EXPRESSION = "(SELECT encode(extensions.digest(jsonb_build_object('round',to_jsonb(a),'submissions',(SELECT jsonb_agg(to_jsonb(s) ORDER BY submission_id) FROM public.lab_arena_submissions s WHERE round_id=a.round_id),'runs',(SELECT jsonb_agg(to_jsonb(r) ORDER BY run_id) FROM public.lab_arena_runs r WHERE round_id=a.round_id),'ledger',(SELECT string_agg(encode(extensions.digest(to_jsonb(l)::text,'sha256'),'hex'),'' ORDER BY entry_id) FROM public.lab_arena_runs linked CROSS JOIN LATERAL (SELECT l.* FROM public.lab_arena_ledger l WHERE l.run_id=linked.run_id AND l.round_id=a.round_id AND l.entry_id<=(a.configuration_doc->>'recovery_ledger_max')::bigint OFFSET 0) l WHERE linked.round_id=a.round_id AND linked.kind='score'),'events',(SELECT string_agg(encode(extensions.digest(to_jsonb(e)::text,'sha256'),'hex'),'' ORDER BY trajectory_id) FROM public.lab_arena_runs linked CROSS JOIN LATERAL (SELECT e.* FROM public.lab_arena_trajectory_events e WHERE e.run_id=linked.run_id AND e.round_id=a.round_id AND e.trajectory_id<=(a.configuration_doc->>'recovery_events_max')::bigint OFFSET 0) e WHERE linked.round_id=a.round_id AND linked.kind='score'))::text,'sha256'),'hex') FROM public.lab_arena_rounds a WHERE a.round_id='arena-2026-10-10-r445archive' AND a.status='cancelled' AND NOT a.rewards_enabled)"
